      const r = small ? 20 : 27;
      return [
        new THREE.Vector3(bc.x - r, 0, bc.z - r),
        new THREE.Vector3(bc.x + r, 0, bc.z - r),
        new THREE.Vector3(bc.x + r, 0, bc.z + r),
